  /// Evaluates the true ANN MLP forward pass with ReLU activations
  static double predict(List<double> features) {
    // 1. Standard Scaler
    final scaled = List<double>.generate(8, (i) => (features[i] - scalerMean[i]) / scalerScale[i]);

    // 2. Dense Layer 1 (64 units + ReLU)
    final h1 = List<double>.filled(64, 0.0);
    for (int j = 0; j < 64; j++) {
      double sum = b1[j];
      for (int i = 0; i < 8; i++) {
        sum += scaled[i] * w1[i][j];
      }
      h1[j] = sum > 0.0 ? sum : 0.0;
    }

    // 3. Dense Layer 2 (32 units + ReLU)
    final h2 = List<double>.filled(32, 0.0);
    for (int k = 0; k < 32; k++) {
      double sum = b2[k];
      for (int j = 0; j < 64; j++) {
        sum += h1[j] * w2[j][k];
      }
      h2[k] = sum > 0.0 ? sum : 0.0;
    }

    // 4. Output Layer (1 unit, linear)
    double out = b3[0];
    for (int k = 0; k < 32; k++) {
      out += h2[k] * w3[k][0];
    }
    return out;
